/**
 * SINGLE source of truth for logo files (paths + intrinsic sizes). Only <Logo/> reads LOGOS.
 * Files are generated by `node scripts/build-brand-assets.mjs` from assets/branding/* (official logos).
 *  - color  : official colour logo (light backgrounds)
 *  - mono   : official monochrome charcoal logo (beige / print-like surfaces)
 *  - onDark : derived from the official monochrome logo by recolouring its alpha mask to off-white #F5F2EC
 * Never crop or stretch: width/height below are the real pixel sizes of each file (keep in sync with the script output).
 */
export type LogoVariant = "color" | "mono" | "onDark";

interface Img {
  src: string;
  width: number;
  height: number;
}
export interface LogoFile {
  webp: Img;
  webpSmall: Img;
  png: Img;
}

/** Admin-uploaded logo (settings.branding.*MediaId) resolved server-side; see ./logo-overrides.ts. */
export interface LogoOverride {
  src: string;
  width: number;
  height: number;
  avif: { src: string; width: number }[];
  webp: { src: string; width: number }[];
}
export type LogoOverrides = Partial<Record<LogoVariant, LogoOverride>>;

